*{box-sizing:border-box}
body{font-family:Figtree,'Segoe UI',system-ui,sans-serif;background:#f8fafc;color:#0F172A}
.shell{display:flex;min-height:100vh}
.side{width:220px;background:#fff;border-right:1px solid #E2E8F0;padding:20px 12px;font-size:14px}
.side a{display:block;padding:8px 12px;border-radius:8px;color:#334155;text-decoration:none}
.side a.on{background:#dcf5ec;color:#117b63;font-weight:700}
.main{flex:1;padding:32px;max-width:900px}
.crumb{font-size:13px;color:#64748B}.crumb a{color:#1b8168;text-decoration:none}
h1{font-size:24px;font-weight:700;margin:4px 0 24px}
.form{background:#fff;border:1px solid #E2E8F0;border-radius:12px;padding:32px}
.lbl{font-size:14px;font-weight:600;color:#334155;display:block;margin-bottom:6px}
.inp{width:100%;max-width:520px;border:1px solid #CBD5E1;border-radius:8px;padding:9px 12px;font-size:14px}
.hint{font-size:12.5px;color:#64748B;margin-top:6px}
.field{margin-bottom:20px}
.btn{background:#1b8168;color:#fff;border:0;border-radius:8px;padding:10px 20px;font-weight:700;font-size:14px}
.btn2{background:#fff;color:#334155;border:1px solid #CBD5E1;border-radius:8px;padding:10px 20px;font-weight:600;font-size:14px;margin-left:8px}
fieldset{border:1px solid #E2E8F0;border-radius:10px;padding:16px 20px;margin:0 0 20px}
legend{font-weight:700;font-size:15px;padding:0 6px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px}
.grid .inp{max-width:none}
.note{background:#eaf2ce;color:#56701f;border-radius:8px;padding:10px 14px;font-size:13px;font-weight:600;margin-bottom:20px}
.chips{display:flex;gap:8px;flex-wrap:wrap}
.chip{border:1px solid #CBD5E1;border-radius:8px;padding:6px 10px;font-size:14px;background:#f8fafc}
table{width:100%;border-collapse:collapse;font-size:14px;background:#fff;border:1px solid #E2E8F0;border-radius:12px}
td,th{padding:10px 14px;border-bottom:1px solid #E2E8F0;text-align:left}
th{font-size:12px;color:#64748B;text-transform:uppercase;letter-spacing:.03em}
.tag{font-size:12px;border-radius:6px;padding:2px 8px;font-weight:700}
.tag-set{background:#dcf5ec;color:#117b63}.tag-inh{background:#f1f5f9;color:#64748B}
.stage2{opacity:.6}
@media (max-width:700px){.side{display:none}.main{padding:16px}.form{padding:18px}}

