:root{--ink:#1e2e27;--ink-soft:#5c7069;--cream:#f4f8f0;--paper:#fff;--line:#e2eadf;--line-strong:#cbdac7;--mint:#1b8168;--mint-soft:#d8f0e6;--lime-soft:#eaf2ce;--lime-fg:#56701f;--danger:#b23b3b;--danger-soft:#f6e4e2;--stage:#edf1ea}
*{box-sizing:border-box}
body{font-family:Figtree,'Segoe UI',system-ui,sans-serif;color:var(--ink);background:var(--stage)}
.wrap{max-width:560px;margin:0 auto;padding:20px 16px}
h1{font-family:'Bricolage Grotesque','Segoe UI',sans-serif;font-size:24px;margin:0}
.soft{color:var(--ink-soft);font-size:12.5px}
.card{background:var(--paper);border:1px solid var(--line);border-radius:22px;padding:20px;margin-top:16px}
.row{background:var(--cream);border:1px solid var(--line);border-radius:16px;padding:14px 15px;margin-top:10px;display:flex;align-items:center;gap:12px}
.btn{min-height:44px;width:100%;border:0;border-radius:13px;background:var(--mint);color:#fff;font-weight:800;font-size:13.5px;padding:11px 16px;margin-top:14px}
.btn-ghost{border:1px solid var(--line);background:var(--paper);color:var(--ink);border-radius:12px;padding:8px 16px;font-weight:600;font-size:13px}
.pill{display:inline-block;border-radius:999px;padding:2px 10px;font-size:10.5px;font-weight:800}
.pill-mint{background:var(--mint-soft);color:var(--mint)}
.pill-lime{background:var(--lime-soft);color:var(--lime-fg)}
.seg{display:flex;gap:8px;margin-top:8px}
.seg button{flex:1;min-height:44px;border:1px solid var(--line-strong);background:var(--paper);border-radius:12px;font-weight:700;font-size:14px;color:var(--ink)}
.seg button[aria-pressed=true]{background:var(--mint);border-color:var(--mint);color:#fff}
label.l{font-size:13px;font-weight:700;display:block;margin-top:14px}
input.t{width:100%;min-height:44px;border:1px solid var(--line-strong);border-radius:12px;padding:10px 12px;font-size:14px;margin-top:6px;background:var(--paper)}
.info{background:var(--lime-soft);color:var(--lime-fg);border-radius:14px;padding:10px 13px;font-size:12.5px;font-weight:600;margin-top:12px}
.chk{width:24px;height:24px;border-radius:7px;border:2px solid var(--line-strong);flex:none;display:flex;align-items:center;justify-content:center;font-weight:900;color:#fff}
.chk.on{background:var(--mint);border-color:var(--mint)}

